using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using C01.Ship.V5;
using C01.Ship.V5.Editor;
using C01.Ship.V61.Signage;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// The manifest is generated by C01SourceV62/design_v62.py. Scene and master
// are built from those same wall, lift and bridge placements.
public static class ShipV67PolishBuilder
{
    const string Root = "Assets/C01ShipV67";
    public const string ScenePath = Root + "/Scenes/C01_Ship_Multideck_v67.unity";
    public const string MasterPath = Root + "/Prefabs/C01_SHIP_MASTER_V67.prefab";
    [Serializable] public class Manifest { public Wall[] walls; public Lift[] lifts; public string[] removedLandingButtons; public Prop[] bridge; }
    [Serializable] public class Wall { public string id; public float y, height; public float[] stripeCenters; }
    [Serializable] public class Lift { public string id; public float halfX,halfZ,doorMin,doorMax,doorWidth,roofHeight,buttonZ; public Panel[] panels; }
    [Serializable] public class Panel { public string id,role; public float[] center,size; }
    [Serializable] public class Prop { public string id,kind; public float[] position; }

    static readonly Dictionary<string, Mesh> meshes = new Dictionary<string, Mesh>();
    static readonly Dictionary<string, GameObject> prefabs = new Dictionary<string, GameObject>();
    static Material panel, metal, dark, screen, trim;
    static Vector3 V(float[] x) => new Vector3(x[0],x[1],x[2]);
    static string Key(float v) => Mathf.RoundToInt(v * 10000).ToString();

    static Material Material(string name)
    {
        var result = AssetDatabase.LoadAssetAtPath<Material>("Assets/C01ShipV6/Materials/" + name + ".mat");
        if (result == null) throw new Exception("Missing material " + name);
        return result;
    }
    static T SaveAsset<T>(T obj, string path) where T : UnityEngine.Object
    {
        var existing = AssetDatabase.LoadAssetAtPath<T>(path);
        if (existing != null) { EditorUtility.CopySerialized(obj, existing); UnityEngine.Object.DestroyImmediate(obj); return existing; }
        AssetDatabase.CreateAsset(obj, path); return obj;
    }

    static Mesh BoxMesh(Vector3 size)
    {
        var key = "box_"+Key(size.x)+"_"+Key(size.y)+"_"+Key(size.z);
        if (meshes.TryGetValue(key, out var mesh)) return mesh;
        float x=size.x/2,z=size.z/2;
        var part = new PartDataV5 { outline=new[]{-x,-z,x,-z,x,z,-x,z}, y0=-size.y/2, y1=size.y/2 };
        mesh = SaveAsset(ShipV67Builder.Prism(part), Root+"/Meshes/"+key+".asset");
        meshes.Add(key,mesh); return mesh;
    }
    static void Box(Transform parent, string name, Vector3 center, Vector3 size, Material material)
    {
        var go=new GameObject(name); go.transform.SetParent(parent,false); go.transform.localPosition=center;
        go.AddComponent<MeshFilter>().sharedMesh=BoxMesh(size);
        go.AddComponent<MeshRenderer>().sharedMaterial=material;
        var collider=go.AddComponent<BoxCollider>(); collider.size=size;
    }
    static GameObject PanelPrefab(Vector3 size)
    {
        string key="CABIN_"+Key(size.x)+"_"+Key(size.y)+"_"+Key(size.z);
        if(prefabs.TryGetValue(key,out var prefab)) return prefab;
        var root=new GameObject(key);
        root.AddComponent<MeshFilter>().sharedMesh=BoxMesh(size);
        root.AddComponent<MeshRenderer>().sharedMaterial=panel;
        var collider=root.AddComponent<BoxCollider>(); collider.size=size;
        prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/Prefabs/Modules/"+key+".prefab");
        UnityEngine.Object.DestroyImmediate(root); prefabs.Add(key,prefab); return prefab;
    }
    static GameObject BridgePrefab(string kind)
    {
        if(prefabs.TryGetValue(kind,out var prefab)) return prefab;
        var g=new GameObject("BRIDGE_"+kind);
        if(kind=="chair" || kind=="captain")
        {
            float width=kind=="captain"?1.35f:1.0f;
            Box(g.transform,"pedestal",new Vector3(0,.25f,0),new Vector3(.55f,.5f,.55f),metal);
            Box(g.transform,"seat",new Vector3(0,.62f,0),new Vector3(.95f,.24f,width),dark);
            Box(g.transform,"back",new Vector3(.4f,1.15f,0),new Vector3(.15f,.82f,width),panel);
            Box(g.transform,"arm_L",new Vector3(-.075f,.82f,-width/2+.07f),new Vector3(.8f,.16f,.14f),trim);
            Box(g.transform,"arm_R",new Vector3(-.075f,.82f,width/2-.07f),new Vector3(.8f,.16f,.14f),trim);
        }
        else if(kind=="console")
        {
            Box(g.transform,"base",new Vector3(0,.45f,0),new Vector3(.9f,.9f,1.8f),dark);
            Box(g.transform,"controls",new Vector3(0,.92f,0),new Vector3(.8f,.04f,1.62f),screen);
            Box(g.transform,"edge",new Vector3(.43f,1.02f,0),new Vector3(.04f,.2f,1.8f),trim);
        }
        else if(kind=="screen")
        {
            Box(g.transform,"base",new Vector3(0,.18f,0),new Vector3(.35f,.36f,2.8f),metal);
            Box(g.transform,"display",new Vector3(0,1.62f,0),new Vector3(.18f,2.52f,2.58f),screen);
            Box(g.transform,"left",new Vector3(0,1.62f,-1.345f),new Vector3(.3f,2.52f,.11f),dark);
            Box(g.transform,"right",new Vector3(0,1.62f,1.345f),new Vector3(.3f,2.52f,.11f),dark);
            Box(g.transform,"top",new Vector3(0,2.93f,0),new Vector3(.3f,.1f,2.8f),metal);
        }
        else throw new Exception("Unknown bridge model " + kind);
        prefab=PrefabUtility.SaveAsPrefabAsset(g,Root+"/Prefabs/Modules/BRIDGE_"+kind+".prefab");
        UnityEngine.Object.DestroyImmediate(g); prefabs.Add(kind,prefab); return prefab;
    }

    // A painted band is a submesh in the wall's own surface. It has no offset,
    // extra collider, overlapping decorative object or geometry beyond the wall.
    static Mesh AlignedWallMesh(Wall wall)
    {
        int phase=Mathf.RoundToInt(Mathf.Repeat(wall.y,3)*10000);
        string key="wall_"+Key(wall.height)+"_"+phase;
        if(meshes.TryGetValue(key,out var mesh)) return mesh;
        var cuts=new List<float>{0,wall.height};
        foreach(float center in wall.stripeCenters)
        {
            cuts.Add(Mathf.Clamp(center-wall.y-.06f,0,wall.height));
            cuts.Add(Mathf.Clamp(center-wall.y+.06f,0,wall.height));
        }
        cuts=cuts.Distinct().OrderBy(x=>x).ToList();
        var verts=new List<Vector3>(); var plain=new List<int>(); var band=new List<int>();
        void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,Vector3 normal,bool stripe)
        {
            int n=verts.Count; verts.Add(a);verts.Add(b);verts.Add(c);verts.Add(d);
            var t=stripe?band:plain;
            if(Vector3.Dot(Vector3.Cross(b-a,c-a),normal)>=0) t.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});
            else t.AddRange(new[]{n,n+2,n+1,n,n+3,n+2});
        }
        const float l=.15f,r=2.85f,z=.15f;
        for(int i=0;i<cuts.Count-1;i++)
        {
            float a=cuts[i],b=cuts[i+1]; if(b-a<.00001f) continue;
            float global=wall.y+(a+b)/2;
            bool stripe=wall.stripeCenters.Any(c=>Mathf.Abs(global-c)<.06001f);
            Quad(new Vector3(l,a,z),new Vector3(r,a,z),new Vector3(r,b,z),new Vector3(l,b,z),Vector3.forward,stripe);
            Quad(new Vector3(l,a,-z),new Vector3(r,a,-z),new Vector3(r,b,-z),new Vector3(l,b,-z),Vector3.back,stripe);
        }
        Quad(new Vector3(l,0,-z),new Vector3(l,0,z),new Vector3(l,wall.height,z),new Vector3(l,wall.height,-z),Vector3.left,false);
        Quad(new Vector3(r,0,-z),new Vector3(r,0,z),new Vector3(r,wall.height,z),new Vector3(r,wall.height,-z),Vector3.right,false);
        Quad(new Vector3(l,0,-z),new Vector3(r,0,-z),new Vector3(r,0,z),new Vector3(l,0,z),Vector3.down,false);
        Quad(new Vector3(l,wall.height,-z),new Vector3(r,wall.height,-z),new Vector3(r,wall.height,z),new Vector3(l,wall.height,z),Vector3.up,false);
        mesh=new Mesh{name=key};mesh.SetVertices(verts);mesh.subMeshCount=2;mesh.SetTriangles(plain,0);mesh.SetTriangles(band,1);
        mesh.RecalculateNormals();mesh.RecalculateBounds();
        mesh=SaveAsset(mesh,Root+"/Meshes/"+key+".asset"); meshes.Add(key,mesh); return mesh;
    }

    [MenuItem("Tools/C01 Ship v6.7/Build final")]
    public static void Build()
    {
        if(EditorApplication.isPlayingOrWillChangePlaymode) throw new Exception("Stop Play mode before rebuilding");
        if(Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Any(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty))
            throw new Exception("Save all open scenes before rebuilding");
        var data=JsonUtility.FromJson<Manifest>(File.ReadAllText(Root+"/Data/polish_v67.json"));
        if(data==null || data.walls.Length==0 || data.lifts.Length!=6) throw new Exception("Invalid repair manifest");
        foreach(var folder in new[]{"Meshes","Prefabs/Modules","Scenes"}) Directory.CreateDirectory(Root+"/"+folder);
        AssetDatabase.Refresh(); meshes.Clear();prefabs.Clear();
        panel=Material("PANEL");metal=Material("METAL");dark=Material("DARK");screen=Material("SCREEN");trim=Material("TRIM");
        var scene=EditorSceneManager.OpenScene("Assets/C01ShipV67/Scenes/C01_Ship_Multideck_v67_base.unity");
        var explorer=UnityEngine.Object.FindFirstObjectByType<ShipExplorerV5>();
        if(explorer==null || explorer.master==null) throw new Exception("Missing original ship master");
        var master=explorer.master;
        var signage=master.GetComponent<ButtonSignage>(); if(signage==null) { signage=master.AddComponent<ButtonSignage>(); signage.Configure(AssetDatabase.LoadAssetAtPath<Shader>("Assets/C01ShipV61/Signage/ButtonText.shader")); } signage.enabled=false;
        var removed=new HashSet<string>(data.removedLandingButtons ?? Array.Empty<string>());
        int removedCount=0;
        foreach(var button in explorer.buttons)
        {
            if(button==null) continue;
            var marker=button.GetComponent<ShipInstanceV5>();
            if(marker!=null && removed.Contains(marker.placementId))
            {
                UnityEngine.Object.DestroyImmediate(button.gameObject);
                removedCount++;
            }
        }
        if(removedCount!=removed.Count) throw new Exception("Missing shaft-side landing buttons");
        explorer.buttons=explorer.buttons.Where(b=>b!=null).ToArray();
        var wallMap=master.GetComponentsInChildren<ShipInstanceV5>(true).Where(x=>x.category=="Walls").ToDictionary(x=>x.placementId);
        foreach(var wall in data.walls)
        {
            if(!wallMap.TryGetValue(wall.id,out var instance)) throw new Exception("Missing wall " + wall.id);
            var parts=instance.GetComponentsInChildren<ShipSolidV5>(true).OrderBy(x=>x.partIndex).ToArray();
            if(parts.Length==0) throw new Exception("No wall geometry " + wall.id);
            for(int i=0;i<parts.Length;i++)
            {
                var f=parts[i].GetComponent<MeshFilter>();var r=parts[i].GetComponent<MeshRenderer>();
                if(f==null||r==null) throw new Exception("Wall renderer missing " + wall.id);
                f.sharedMesh=i==0?AlignedWallMesh(wall):null;
                if(i==0) r.sharedMaterials=new[]{panel,metal};
                PrefabUtility.RecordPrefabInstancePropertyModifications(f);
                if(i==0) PrefabUtility.RecordPrefabInstancePropertyModifications(r);
            }
        }
        // Fascia nodes used the panel material and interrupted vertical seams.
        // Keep one continuous node finish through full and remainder modules.
        foreach(var node in master.GetComponentsInChildren<ShipInstanceV5>(true)
                    .Where(x=>x.category=="Nodes" && x.modelId!=null && x.modelId.EndsWith("_FASCIA")))
        {
            foreach(var r in node.GetComponentsInChildren<MeshRenderer>(true))
            {
                r.sharedMaterial=metal;
                PrefabUtility.RecordPrefabInstancePropertyModifications(r);
            }
        }
        var lifts=explorer.lifts.ToDictionary(x=>x.id);
        foreach(var lift in data.lifts)
        {
            if(!lifts.TryGetValue(lift.id,out var control)||control.car==null) throw new Exception("Missing lift " + lift.id);
            // Passenger cars had low guard rails. Remove those pieces when adding
            // full-height cabin panels; the platform and its collider are retained.
            foreach(var old in control.car.GetComponentsInChildren<ShipSolidV5>(true).Where(x=>x.role=="DARK").ToArray())
                UnityEngine.Object.DestroyImmediate(old.gameObject);
            foreach(var p in lift.panels)
            {
                var g=(GameObject)PrefabUtility.InstantiatePrefab(PanelPrefab(V(p.size)),control.car);
                g.name=p.id;g.transform.localPosition=V(p.center);g.transform.localRotation=Quaternion.identity;
                var m=g.AddComponent<ShipInstanceV5>();m.placementId=p.id;m.modelId="V62_CABIN_"+p.role;m.category="LiftCars";m.deck=-1;
            }
            // Mount controls on the inner face of the new side wall, so neither
            // their display nor their click collider is buried in the cabin.
            foreach(var button in control.car.GetComponentsInChildren<ShipButtonV5>(true))
            {
                var p=button.transform.localPosition;p.z=lift.buttonZ;button.transform.localPosition=p;
                PrefabUtility.RecordPrefabInstancePropertyModifications(button.transform);
            }
        }
        var group=new GameObject("V62_BRIDGE_COMMAND");group.transform.SetParent(master.transform,false);
        foreach(var p in data.bridge)
        {
            var g=(GameObject)PrefabUtility.InstantiatePrefab(BridgePrefab(p.kind),group.transform);
            g.name=p.id;g.transform.localPosition=V(p.position);
            var m=g.AddComponent<ShipInstanceV5>();m.placementId=p.id;m.modelId="V62_BRIDGE_"+p.kind;m.category="Props";m.zoneId="L1_BRIDGE";m.deck=1;
        }
        var bridgeLight=GameObject.Find("Light_L1_BRIDGE");
        if(bridgeLight!=null){var l=bridgeLight.GetComponent<Light>();if(l!=null){l.range=34;l.intensity=4;l.color=new Color(.78f,.88f,1);}}
        if(signage!=null) { signage.enabled=true; PrefabUtility.RecordPrefabInstancePropertyModifications(signage); }
        explorer.InvalidateSceneCache(); explorer.SetWalking(true);
        // Keep the master as a prefab variant: unchanged modules remain linked to v6.
        var saved=PrefabUtility.SaveAsPrefabAssetAndConnect(master,MasterPath,InteractionMode.AutomatedAction);
        if(saved==null) throw new Exception("Could not save v6.2 master prefab");
        EditorSceneManager.MarkSceneDirty(scene);
        if(!EditorSceneManager.SaveScene(scene,ScenePath)) throw new Exception("Could not save v6.2 scene");
        if(!EditorBuildSettings.scenes.Any(s=>s.path==ScenePath))
            EditorBuildSettings.scenes=EditorBuildSettings.scenes.Concat(new[]{new EditorBuildSettingsScene(ScenePath,true)}).ToArray();
        AssetDatabase.SaveAssets();
        Debug.Log("C01 V6.5 BUILD COMPLETE walls="+data.walls.Length+" cabins="+data.lifts.Length+" bridge="+data.bridge.Length);
    }
}
